const FOCUSABLE_SELECTOR = [
  'a[href]',
  'area[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'iframe',
  'object',
  'embed',
  '[contenteditable="true"]',
  '[tabindex]:not([tabindex="-1"])',
].join(',')

function isFocusable(element: HTMLElement) {
  return (
    !element.hidden &&
    element.getAttribute('aria-hidden') !== 'true' &&
    !element.closest('[inert]') &&
    element.getClientRects().length > 0
  )
}

export function getFocusableElements(container: HTMLElement) {
  return Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR)).filter(
    isFocusable,
  )
}

export function focusFirst(container: HTMLElement, preferred?: HTMLElement | null) {
  const target =
    (preferred && container.contains(preferred) && isFocusable(preferred) ? preferred : null) ??
    getFocusableElements(container)[0] ??
    container

  target.focus({ preventScroll: true })
  return target
}

export function keepTabFocusInside(event: KeyboardEvent, container: HTMLElement) {
  if (event.key !== 'Tab') return

  const focusable = getFocusableElements(container)
  if (focusable.length === 0) {
    event.preventDefault()
    container.focus({ preventScroll: true })
    return
  }

  const first = focusable[0]
  const last = focusable[focusable.length - 1]
  const active = container.ownerDocument.activeElement

  if (event.shiftKey && (active === first || !container.contains(active))) {
    event.preventDefault()
    last.focus({ preventScroll: true })
  } else if (!event.shiftKey && (active === last || !container.contains(active))) {
    event.preventDefault()
    first.focus({ preventScroll: true })
  }
}

import { expect, test as base, type Page } from '@playwright/test'
import { resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const distDirectory = fileURLToPath(new URL('../dist/demo/', import.meta.url))

type WorkerFixtures = {
  sharedPage: Page
}

const test = base.extend<{}, WorkerFixtures>({
  sharedPage: [
    async ({ browser }, use) => {
      const context = await browser.newContext()
      const page = await context.newPage()

      await page.route('http://dialog.test/**', async (route) => {
        const pathname = new URL(route.request().url()).pathname
        const relativePath = pathname === '/' ? 'index.html' : pathname.slice(1)
        const filePath = resolve(distDirectory, relativePath)

        if (!filePath.startsWith(distDirectory)) {
          await route.abort('blockedbyclient')
          return
        }

        await route.fulfill({ path: filePath })
      })

      await use(page)
      await context.close()
    },
    { scope: 'worker' },
  ],
})

test.beforeEach(async ({ sharedPage }) => {
  await sharedPage.goto('/')
})

test('traps focus, closes with Escape, and restores the trigger', async ({
  sharedPage: page,
}) => {
  const trigger = page.getByRole('button', { name: 'Edit profile' })
  await trigger.click()

  const dialog = page.getByRole('dialog', { name: 'Edit profile' })
  await expect(dialog).toBeVisible()
  await expect(dialog).toHaveAttribute('aria-modal', 'true')
  await expect(dialog).toHaveAccessibleDescription('Update your public information.')
  await expect(dialog.getByLabel('Name')).toBeFocused()

  const background = page.locator('#root')
  await expect(background).toHaveAttribute('aria-hidden', 'true')
  await expect(background).toHaveJSProperty('inert', true)

  await page.locator('a[href="#background"]').evaluate((element: HTMLAnchorElement) =>
    element.focus(),
  )
  await expect(dialog.getByLabel('Name')).toBeFocused()

  await page.keyboard.press('Shift+Tab')
  await expect(dialog.getByRole('button', { name: 'Close' })).toBeFocused()
  await page.keyboard.press('Tab')
  await expect(dialog.getByLabel('Name')).toBeFocused()

  await page.keyboard.press('Escape')
  await expect(dialog).toBeHidden()
  await expect(trigger).toBeFocused()
  await expect(background).not.toHaveAttribute('aria-hidden', 'true')
  await expect(background).toHaveJSProperty('inert', false)
})

test('only the top nested dialog handles Escape and restores local focus', async ({
  sharedPage: page,
}) => {
  await page.getByRole('button', { name: 'Edit profile' }).click()
  const parent = page.getByRole('dialog', { name: 'Edit profile' })
  const nestedTrigger = parent.getByRole('button', { name: 'Open permissions' })
  await nestedTrigger.click()

  const child = page.getByRole('dialog', { name: 'Permissions' })
  await expect(child).toBeVisible()
  await expect(child.getByRole('button', { name: 'Save permissions' })).toBeFocused()

  await page.keyboard.press('Escape')
  await expect(child).toBeHidden()
  await expect(parent).toBeVisible()
  await expect(nestedTrigger).toBeFocused()

  await page.keyboard.press('Escape')
  await expect(parent).toBeHidden()
})

import {
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type MutableRefObject,
  type ReactNode,
  type Ref,
  type RefObject,
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { createPortal } from 'react-dom'

import { focusFirst, keepTabFocusInside } from './dialog/focus'
import { isTopModal, registerModal } from './dialog/modalStack'

const useBrowserLayoutEffect = typeof document === 'undefined' ? useEffect : useLayoutEffect

export type DialogOpenChangeReason = 'close' | 'escape' | 'outside' | 'trigger'

export type DialogOpenChangeDetails = {
  reason: DialogOpenChangeReason
}

export type DialogRootProps = {
  children: ReactNode
  defaultOpen?: boolean
  onOpenChange?: (open: boolean, details: DialogOpenChangeDetails) => void
  open?: boolean
}

type DialogContextValue = {
  contentId: string
  contentRef: MutableRefObject<HTMLDivElement | null>
  descriptionId: string
  hasDescription: boolean
  hasTitle: boolean
  open: boolean
  requestOpenChange: (open: boolean, reason: DialogOpenChangeReason) => void
  setHasDescription: (mounted: boolean) => void
  setHasTitle: (mounted: boolean) => void
  titleId: string
  triggerRef: MutableRefObject<HTMLButtonElement | null>
}

const DialogContext = createContext<DialogContextValue | null>(null)

function useDialogContext(component: string) {
  const context = useContext(DialogContext)
  if (!context) throw new Error(`${component} must be used inside Dialog.Root`)
  return context
}

export function DialogRoot({
  children,
  defaultOpen = false,
  onOpenChange,
  open: controlledOpen,
}: DialogRootProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isControlled = controlledOpen !== undefined
  const open = isControlled ? controlledOpen : uncontrolledOpen
  const triggerRef = useRef<HTMLButtonElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)
  const [hasTitle, setHasTitle] = useState(false)
  const [hasDescription, setHasDescription] = useState(false)
  const reactId = useId()
  const idBase = `dialog-${reactId.replace(/:/g, '')}`

  const requestOpenChange = useCallback(
    (nextOpen: boolean, reason: DialogOpenChangeReason) => {
      if (nextOpen === open) return
      if (!isControlled) setUncontrolledOpen(nextOpen)
      onOpenChange?.(nextOpen, { reason })
    },
    [isControlled, onOpenChange, open],
  )

  const value = useMemo<DialogContextValue>(
    () => ({
      contentId: `${idBase}-content`,
      contentRef,
      descriptionId: `${idBase}-description`,
      hasDescription,
      hasTitle,
      open,
      requestOpenChange,
      setHasDescription,
      setHasTitle,
      titleId: `${idBase}-title`,
      triggerRef,
    }),
    [hasDescription, hasTitle, idBase, open, requestOpenChange],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

function assignRef<T>(ref: Ref<T> | undefined, value: T | null) {
  if (typeof ref === 'function') ref(value)
  else if (ref) ref.current = value
}

export type DialogTriggerProps = ButtonHTMLAttributes<HTMLButtonElement>

export const DialogTrigger = forwardRef<HTMLButtonElement, DialogTriggerProps>(
  function DialogTrigger({ onClick, type = 'button', ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Trigger')

    return (
      <button
        {...props}
        aria-controls={context.contentId}
        aria-expanded={context.open}
        aria-haspopup="dialog"
        ref={(element) => {
          context.triggerRef.current = element
          assignRef(forwardedRef, element)
        }}
        type={type}
        onClick={(event) => {
          onClick?.(event)
          if (!event.defaultPrevented) context.requestOpenChange(true, 'trigger')
        }}
      />
    )
  },
)

export type DialogPortalProps = {
  children: ReactNode
  container?: HTMLElement | null
}

export function DialogPortal({ children, container }: DialogPortalProps) {
  const { open } = useDialogContext('Dialog.Portal')
  const [host, setHost] = useState<HTMLDivElement | null>(null)

  useBrowserLayoutEffect(() => {
    if (!open) return

    const target = container ?? document.body
    const portalHost = target.ownerDocument.createElement('div')
    portalHost.dataset.dialogPortal = ''
    target.appendChild(portalHost)
    setHost(portalHost)

    return () => {
      portalHost.remove()
      setHost(null)
    }
  }, [container, open])

  if (!open || !host) return null
  return createPortal(children, host)
}

export type DialogOverlayProps = HTMLAttributes<HTMLDivElement>

export const DialogOverlay = forwardRef<HTMLDivElement, DialogOverlayProps>(
  function DialogOverlay({ onClick, ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Overlay')

    return (
      <div
        {...props}
        data-state={context.open ? 'open' : 'closed'}
        ref={forwardedRef}
        onClick={(event) => {
          onClick?.(event)
          if (
            !event.defaultPrevented &&
            event.target === event.currentTarget &&
            isTopModal(context.contentRef.current)
          ) {
            context.requestOpenChange(false, 'outside')
          }
        }}
      />
    )
  },
)

export type DialogContentProps = Omit<HTMLAttributes<HTMLDivElement>, 'id'> & {
  id?: never
  initialFocusRef?: RefObject<HTMLElement | null>
  onCloseAutoFocus?: (event: Event) => void
  onEscapeKeyDown?: (event: KeyboardEvent) => void
  onOpenAutoFocus?: (event: Event) => void
}

export const DialogContent = forwardRef<HTMLDivElement, DialogContentProps>(
  function DialogContent(
    {
      'aria-describedby': ariaDescribedBy,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      initialFocusRef,
      onCloseAutoFocus,
      onEscapeKeyDown,
      onOpenAutoFocus,
      ...props
    },
    forwardedRef,
  ) {
    const context = useDialogContext('Dialog.Content')
    const latestContext = useRef(context)
    latestContext.current = context
    const latestCallbacks = useRef({ onCloseAutoFocus, onEscapeKeyDown, onOpenAutoFocus })
    latestCallbacks.current = { onCloseAutoFocus, onEscapeKeyDown, onOpenAutoFocus }
    const lastFocusedInside = useRef<HTMLElement | null>(null)
    const registered = useRef(false)

    useBrowserLayoutEffect(() => {
      const content = context.contentRef.current
      if (!content) return

      registered.current = true
      const unregister = registerModal({
        content,
        handleKeyDown(event) {
          if (event.key === 'Escape') {
            latestCallbacks.current.onEscapeKeyDown?.(event)
            if (!event.defaultPrevented) {
              event.preventDefault()
              event.stopPropagation()
              latestContext.current.requestOpenChange(false, 'escape')
            }
            return
          }
          keepTabFocusInside(event, content)
        },
        redirectFocus() {
          focusFirst(content, lastFocusedInside.current)
        },
        restoreFocus() {
          if (registered.current) return
          const event = new Event('dialog.closeAutoFocus', { cancelable: true })
          latestCallbacks.current.onCloseAutoFocus?.(event)
          const trigger = latestContext.current.triggerRef.current
          if (!event.defaultPrevented && trigger?.isConnected) {
            trigger.focus({ preventScroll: true })
          }
        },
      })

      const event = new Event('dialog.openAutoFocus', { cancelable: true })
      latestCallbacks.current.onOpenAutoFocus?.(event)
      if (!event.defaultPrevented) focusFirst(content, initialFocusRef?.current)

      return () => {
        registered.current = false
        unregister()
      }
    }, [context.contentRef, context.triggerRef, initialFocusRef])

    return (
      <div
        {...props}
        aria-describedby={ariaDescribedBy ?? (context.hasDescription ? context.descriptionId : undefined)}
        aria-label={ariaLabel}
        aria-labelledby={
          ariaLabelledBy ?? (!ariaLabel && context.hasTitle ? context.titleId : undefined)
        }
        aria-modal="true"
        data-state={context.open ? 'open' : 'closed'}
        id={context.contentId}
        ref={(element) => {
          context.contentRef.current = element
          assignRef(forwardedRef, element)
        }}
        role="dialog"
        tabIndex={props.tabIndex ?? -1}
        onFocusCapture={(event) => {
          props.onFocusCapture?.(event)
          if (!event.defaultPrevented) lastFocusedInside.current = event.target as HTMLElement
        }}
      />
    )
  },
)

export type DialogTitleProps = Omit<HTMLAttributes<HTMLHeadingElement>, 'id'> & { id?: never }

export const DialogTitle = forwardRef<HTMLHeadingElement, DialogTitleProps>(
  function DialogTitle(props, forwardedRef) {
    const context = useDialogContext('Dialog.Title')
    useBrowserLayoutEffect(() => {
      context.setHasTitle(true)
      return () => context.setHasTitle(false)
    }, [context.setHasTitle])
    return <h2 {...props} id={context.titleId} ref={forwardedRef} />
  },
)

export type DialogDescriptionProps = Omit<HTMLAttributes<HTMLParagraphElement>, 'id'> & {
  id?: never
}

export const DialogDescription = forwardRef<HTMLParagraphElement, DialogDescriptionProps>(
  function DialogDescription(props, forwardedRef) {
    const context = useDialogContext('Dialog.Description')
    useBrowserLayoutEffect(() => {
      context.setHasDescription(true)
      return () => context.setHasDescription(false)
    }, [context.setHasDescription])
    return <p {...props} id={context.descriptionId} ref={forwardedRef} />
  },
)

export type DialogCloseProps = ButtonHTMLAttributes<HTMLButtonElement>

export const DialogClose = forwardRef<HTMLButtonElement, DialogCloseProps>(
  function DialogClose({ onClick, type = 'button', ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Close')
    return (
      <button
        {...props}
        ref={forwardedRef}
        type={type}
        onClick={(event) => {
          onClick?.(event)
          if (!event.defaultPrevented) context.requestOpenChange(false, 'close')
        }}
      />
    )
  },
)

export const Dialog = Object.freeze({
  Close: DialogClose,
  Content: DialogContent,
  Description: DialogDescription,
  Overlay: DialogOverlay,
  Portal: DialogPortal,
  Root: DialogRoot,
  Title: DialogTitle,
  Trigger: DialogTrigger,
})

type ModalLayer = {
  content: HTMLElement
  handleKeyDown: (event: KeyboardEvent) => void
  redirectFocus: () => void
  restoreFocus: () => void
}

type ElementState = {
  ariaHidden: string | null
  inert: boolean
}

class ModalStack {
  private readonly document: Document
  private readonly layers: ModalLayer[] = []
  private readonly changedElements = new Map<HTMLElement, ElementState>()
  private originalBodyOverflow: string | null = null

  constructor(document: Document) {
    this.document = document
  }

  add(layer: ModalLayer) {
    this.layers.push(layer)
    if (this.layers.length === 1) {
      this.document.addEventListener('keydown', this.handleKeyDown, true)
      this.document.addEventListener('focusin', this.handleFocusIn, true)
      this.originalBodyOverflow = this.document.body.style.overflow
      this.document.body.style.overflow = 'hidden'
    }
    this.syncOutsideContent()

    return () => {
      const index = this.layers.indexOf(layer)
      if (index === -1) return

      this.layers.splice(index, 1)
      this.syncOutsideContent()

      if (this.layers.length === 0) {
        this.document.removeEventListener('keydown', this.handleKeyDown, true)
        this.document.removeEventListener('focusin', this.handleFocusIn, true)
        this.document.body.style.overflow = this.originalBodyOverflow ?? ''
        this.originalBodyOverflow = null
      }

      queueMicrotask(layer.restoreFocus)
    }
  }

  isTop(content: HTMLElement | null) {
    return content !== null && this.layers.at(-1)?.content === content
  }

  private readonly handleKeyDown = (event: KeyboardEvent) => {
    this.layers.at(-1)?.handleKeyDown(event)
  }

  private readonly handleFocusIn = (event: FocusEvent) => {
    const top = this.layers.at(-1)
    if (!top || top.content.contains(event.target as Node)) return
    top.redirectFocus()
  }

  private restoreChangedElements() {
    for (const [element, state] of this.changedElements) {
      element.inert = state.inert
      if (state.ariaHidden === null) element.removeAttribute('aria-hidden')
      else element.setAttribute('aria-hidden', state.ariaHidden)
    }
    this.changedElements.clear()
  }

  private syncOutsideContent() {
    this.restoreChangedElements()

    const top = this.layers.at(-1)
    if (!top) return

    let branch: HTMLElement | null = top.content
    while (branch && branch !== this.document.body) {
      const parent: HTMLElement | null = branch.parentElement
      if (!parent) break

      for (const sibling of Array.from(parent.children)) {
        if (sibling === branch || !(sibling instanceof HTMLElement)) continue
        this.changedElements.set(sibling, {
          ariaHidden: sibling.getAttribute('aria-hidden'),
          inert: sibling.inert,
        })
        sibling.inert = true
        sibling.setAttribute('aria-hidden', 'true')
      }

      branch = parent
    }
  }
}

const stacks = new WeakMap<Document, ModalStack>()

function getStack(document: Document) {
  let stack = stacks.get(document)
  if (!stack) {
    stack = new ModalStack(document)
    stacks.set(document, stack)
  }
  return stack
}

export function registerModal(layer: ModalLayer) {
  return getStack(layer.content.ownerDocument).add(layer)
}

export function isTopModal(content: HTMLElement | null) {
  return content ? getStack(content.ownerDocument).isTop(content) : false
}
